arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/bash
case "$1" in
  *Username*) echo "x-access-token" ;;
  *Password*) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh; cd /tmp/chandler-conv; GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/chandler 2>&1 | tail -5
